package io.sdetflow.api;
import java.util.regex.Pattern;
public final class Redactor { private static final Pattern[] P=new Pattern[]{Pattern.compile("(?i)(authorization\\s*[:=]\\s*(?:bearer|basic)\\s+)([^\\s,;]+)"),Pattern.compile("(?i)(bearer\\s+)([A-Za-z0-9._~+/\\-=]+)"),Pattern.compile("(?i)((?:api[_-]?key|apikey|password|passwd|pwd|secret|access[_-]?token|refresh[_-]?token|client[_-]?secret)\\s*[\\\"']?\\s*[:=]\\s*[\\\"']?)([^\\s,\\\"';}\\]]+)"),Pattern.compile("\\bsk-[A-Za-z0-9_-]{16,}\\b"),Pattern.compile("\\bAIza[A-Za-z0-9_-]{20,}\\b"),Pattern.compile("\\beyJ[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\b")}; private Redactor(){} public static String redact(String in){if(in==null)return null;String o=in;for(Pattern p:P){var m=p.matcher(o);if(p.matcher("Authorization: Bearer x").groupCount()>=2)o=m.replaceAll("$1[REDACTED]");else o=m.replaceAll("[REDACTED]");}return o;} }
